"""Select an original connected direct-course approach and left turn."""
from math import atan2, hypot, isfinite, pi, degrees


def _xy(waypoint):
    location = waypoint.transform.location
    xy = float(location.x), float(location.y)
    if not all(isfinite(v) for v in xy):
        raise ValueError('Nonfinite Native route waypoint')
    return xy


def _heading(waypoint):
    direction = waypoint.transform.get_forward_vector()
    xy = float(direction.x), float(direction.y)
    if not all(isfinite(v) for v in xy) or hypot(*xy) < .1:
        raise ValueError('Invalid Native route heading')
    return atan2(xy[1], xy[0])


def _driving(waypoint):
    return waypoint is not None and 'driving' in str(waypoint.lane_type).lower()


def select_left_turn(carla_map, *, spacing_m=2., approach_steps=6, candidate_index=0):
    if not (isfinite(spacing_m) and spacing_m > 0 and
            type(approach_steps) is int and approach_steps >= 4 and
            type(candidate_index) is int and candidate_index >= 0):
        raise ValueError('Invalid connected-turn route sampling')
    candidates = []
    for start in carla_map.generate_waypoints(spacing_m):
        if not _driving(start) or start.is_junction:
            continue
        approach = [start]
        for _ in range(approach_steps):
            previous = approach[-1]
            next_steps = [item for item in previous.next(spacing_m)
                          if _driving(item) and not item.is_junction and
                          (item.road_id, item.lane_id) == (start.road_id, start.lane_id)]
            if len(next_steps) != 1:
                break
            approach.append(next_steps[0])
        if len(approach) != approach_steps + 1:
            continue
        for junction in approach[-1].next(spacing_m):
            if not _driving(junction) or not junction.is_junction:
                continue
            for exit_wp in junction.next(8.):
                if not _driving(exit_wp) or exit_wp.is_junction:
                    continue
                delta = degrees((_heading(exit_wp) - _heading(approach[-1]) + pi) % (2 * pi) - pi)
                if 45 <= delta <= 135:
                    candidates.append((int(start.road_id), int(start.lane_id), *_xy(start),
                                       {'approach': approach, 'junction': junction,
                                        'exit': exit_wp, 'heading_change_deg': delta}))
    candidates.sort(key=lambda item: item[:4])
    if candidate_index >= len(candidates):
        raise ValueError('No connected left-turn route at requested sampling')
    return candidates[candidate_index][-1]


def route_targets(scene):
    return [list(_xy(waypoint)) for waypoint in
            (*scene['approach'], scene['junction'], scene['exit'])]


def control_step(position_xy, forward_xy, velocity_xy, target_xy,
                 *, target_speed_mps=5., heading_gain=1.4, speed_gain=.25):
    points = [tuple(float(value) for value in pair)
              for pair in (position_xy, forward_xy, velocity_xy, target_xy)]
    if any(len(pair) != 2 or not all(isfinite(v) for v in pair) for pair in points):
        raise ValueError('Invalid Native turn controller readback')
    if not (isfinite(target_speed_mps) and target_speed_mps > 0 and
            isfinite(heading_gain) and heading_gain > 0 and
            isfinite(speed_gain) and speed_gain > 0):
        raise ValueError('Invalid turn engineering gain')
    position, forward, velocity, target = points
    if hypot(*forward) < .1 or hypot(target[0]-position[0], target[1]-position[1]) < .01:
        raise ValueError('Turn heading or target undefined')
    bearing = atan2(target[1]-position[1], target[0]-position[0])
    heading = atan2(forward[1], forward[0])
    angle = (bearing-heading+pi)%(2*pi)-pi
    steer = max(-1.,min(1.,heading_gain*angle/(pi/2)))
    speed_error = target_speed_mps-hypot(*velocity)
    return {'steer':steer, 'throttle':max(0.,min(1.,speed_gain*speed_error)),
            'brake':max(0.,min(1.,-speed_gain*speed_error))}

"""Retain exact Native turn, participant, lamp and listener PCM originals.

The caller must supply audio packets from an actual listener capture. A control
command or a synthetic horn flag is never converted into audio evidence here.
"""
from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path


def _finite(value, label):
    value = float(value)
    if not isfinite(value):
        raise ValueError('Nonfinite original ' + label)
    return value


def _geometry(actor):
    transform = actor.get_transform()
    location = transform.location
    box = actor.bounding_box
    x = _finite(location.x, 'actor x')
    y = _finite(location.y, 'actor y')
    radius = hypot(_finite(box.extent.x, 'body x extent'),
                   _finite(box.extent.y, 'body y extent'))
    if radius <= 0:
        raise ValueError('Original Native body radius is zero')
    return {'x_m': x, 'y_m': y, 'body_radius_m': radius}


def _write_json(path, value):
    path.write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')


class TurnSourceRecorder:
    """Write synchronized originals; caller owns actor and audio lifetimes."""
    def __init__(self, root, ego, participants, listener_id, context,
                 left_light_mask, right_light_mask):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.ego = ego
        self.participants = dict(participants)
        self.listener_id = str(listener_id)
        self.left_mask = int(left_light_mask)
        self.right_mask = int(right_light_mask)
        if not self.listener_id or self.listener_id not in self.participants:
            raise ValueError('Listener needs a retained Native participant')
        if not self.left_mask or not self.right_mask or self.left_mask == self.right_mask:
            raise ValueError('Native left/right light masks required')
        expected = set(context.get('participant_types', {}))
        if expected != set(self.participants):
            raise ValueError('Affected context differs from Native participants')
        for key in ('pedestrian_may_be_affected', 'vehicle_may_be_affected'):
            if type(context.get(key)) is not bool or not context.get(key + '_source'):
                raise ValueError('Affected status needs a separate reviewed source')
        if not context.get('listener_position_source') or not context.get('participant_geometry_source'):
            raise ValueError('Listener and participant geometry need original provenance')
        self.context = dict(context, listener_id=self.listener_id)
        _write_json(self.root / 'affected_participants.json', self.context)
        self.streams = {name: (self.root / name).open('w') for name in
                        ('ego_turn_motion.jsonl', 'ego_signal_audio.jsonl',
                         'participant_bodies.jsonl', 'listener_audio_original.jsonl')}
        self.previous = None
        self.count = 0

    def append(self, frame, time_s, audio_packet):
        if type(frame) is not int or frame < 0:
            raise ValueError('Native frame identity required')
        time_s = _finite(time_s, 'frame time')
        if self.previous is not None:
            prior_frame, prior_time = self.previous
            if frame != prior_frame + 1 or abs(time_s - prior_time - .05) > 1e-4:
                raise ValueError('Native source frames are not joined at 20 Hz')
        no_pedestrian_audio = audio_packet is None and not self.context['pedestrian_may_be_affected']
        if not no_pedestrian_audio:
            if not isinstance(audio_packet, dict) or audio_packet.get('origin') != 'listener_pcm_capture':
                raise ValueError('Original listener PCM packet required; command state is insufficient')
            if audio_packet.get('frame') != frame or audio_packet.get('listener_id') != self.listener_id:
                raise ValueError('Listener PCM packet frame or identity differs')
            samples = audio_packet.get('samples')
            if not isinstance(samples, list) or len(samples) < 8:
                raise ValueError('Listener PCM packet lacks source samples')
            samples = [_finite(sample, 'listener PCM sample') for sample in samples]
            if any(abs(sample) > 1 for sample in samples):
                raise ValueError('Listener PCM sample outside normalized range')
            if not audio_packet.get('capture_source'):
                raise ValueError('Listener PCM capture source is uncited')
        else:
            samples = None
        ego = _geometry(self.ego)
        yaw = _finite(self.ego.get_transform().rotation.yaw, 'ego yaw')
        bodies = {ident: _geometry(actor) for ident, actor in self.participants.items()}
        if not callable(getattr(self.ego, 'get_light_state', None)):
            raise ValueError('Native light-state readback unavailable')
        lights = int(self.ego.get_light_state())
        left = bool(lights & self.left_mask)
        right = bool(lights & self.right_mask)
        if left and right:
            raise ValueError('Ambiguous Native indicator readback')
        indicator = 'left' if left else 'right' if right else 'off'
        packet = (dict(audio_packet, samples=samples) if not no_pedestrian_audio else
                  {'origin': 'not_collected_no_affected_pedestrian', 'frame': frame,
                   'listener_id': self.listener_id, 'samples': None})
        packet['sha256'] = (sha256(json.dumps(samples, separators=(',', ':'), allow_nan=False).encode()).hexdigest()
                            if samples is not None else None)
        rows = {
            'ego_turn_motion.jsonl': dict(frame=frame, time_s=time_s, ego_yaw_deg=yaw, **ego),
            'ego_signal_audio.jsonl': {'frame': frame, 'time_s': time_s,
                                       'listener_id': self.listener_id,
                                       'indicator_readback': indicator,
                                       'listener_audio_samples': samples,
                                       'listener_audio_status': ('not_collected_no_affected_pedestrian'
                                                                 if no_pedestrian_audio else 'original_pcm'),
                                       'listener_packet_sha256': packet['sha256']},
            'participant_bodies.jsonl': {'frame': frame, 'time_s': time_s, 'bodies': bodies},
            'listener_audio_original.jsonl': packet,
        }
        for name, row in rows.items():
            self.streams[name].write(json.dumps(row, allow_nan=False) + '\n')
        self.previous = frame, time_s
        self.count += 1

    def close(self):
        for stream in self.streams.values():
            stream.close()
        if self.count < 3:
            raise ValueError('Native turn source capture has fewer than three frames')
        manifest = {'format': 'worker-turn-original-source-manifest', 'frames': self.count,
                    'listener_id': self.listener_id, 'source_kind': 'native_plus_listener_pcm',
                    'sources': {name: sha256((self.root / name).read_bytes()).hexdigest()
                                for name in (*self.streams, 'affected_participants.json')}}
        _write_json(self.root / 'turn-source-manifest.json', manifest)
        return manifest

"""Four synchronized original RGB source streams for marked-lane cases."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown lane source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior lane camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original lane camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Lane source encoder failed")


class LaneCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named lane source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original lane camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original lane camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Lane source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original lane source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original lane camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Join original turn motion, lamp readback and listener audio samples.

Audio energy is an observation at a declared listener, not a legal threshold
for "clearly audible". Potentially affected participants remain sourced context.
"""

from hashlib import sha256
import json
from math import atan2, cos, isfinite, sin, sqrt, radians
from pathlib import Path


def _json(path, label):
    path = Path(path)
    if not path.is_file():
        raise ValueError('Missing required source: ' + label)
    raw = path.read_bytes()
    if not raw:
        raise ValueError('Empty required source: ' + label)
    try:
        return json.loads(raw), sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid required source: ' + label) from error


def _jsonl(path, label):
    path = Path(path)
    if not path.is_file():
        raise ValueError('Missing required source: ' + label)
    raw = path.read_bytes()
    if not raw:
        raise ValueError('Empty required source: ' + label)
    try:
        return [json.loads(line) for line in raw.splitlines()], sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid required source: ' + label) from error


def _rms(samples):
    if not isinstance(samples, list) or len(samples) < 8:
        raise ValueError('Original listener audio needs at least eight samples per frame')
    values = [float(value) for value in samples]
    if any(not isfinite(value) or abs(value) > 1 for value in values):
        raise ValueError('Original listener audio sample is out of range')
    return sqrt(sum(value * value for value in values) / len(values))


def _body(row, label):
    try:
        x, y, radius = (float(row[key]) for key in ('x_m', 'y_m', 'body_radius_m'))
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError('Missing original body geometry: ' + label) from error
    if not all(isfinite(value) for value in (x, y, radius)) or radius <= 0:
        raise ValueError('Invalid original body geometry: ' + label)
    return x, y, radius


def _closing_proxy(ego_now, ego_prev, other_now, other_prev, dt):
    """Closest constant-velocity approach; descriptive, never a safety decision."""
    rx, ry = other_now[0] - ego_now[0], other_now[1] - ego_now[1]
    vx = (other_now[0] - other_prev[0] - ego_now[0] + ego_prev[0]) / dt
    vy = (other_now[1] - other_prev[1] - ego_now[1] + ego_prev[1]) / dt
    speed2 = vx * vx + vy * vy
    if speed2 < 1e-12:
        return {'closest_approach_time_s': None, 'projected_surface_gap_m': None}
    time_s = max(0.0, -(rx * vx + ry * vy) / speed2)
    gap = sqrt((rx + vx * time_s) ** 2 + (ry + vy * time_s) ** 2) - ego_now[2] - other_now[2]
    return {'closest_approach_time_s': time_s, 'projected_surface_gap_m': gap}


def measure(motion_path, signal_path, context_path, participant_path):
    motion, motion_hash = _jsonl(motion_path, 'ego_turn_motion.jsonl')
    signals, signal_hash = _jsonl(signal_path, 'ego_signal_audio.jsonl')
    context, context_hash = _json(context_path, 'affected_participants.json')
    participants, participant_hash = _jsonl(participant_path, 'participant_bodies.jsonl')
    if len(motion) != len(signals) or len(motion) < 3:
        raise ValueError('Turn motion and signal histories differ or are incomplete')
    if len(participants) != len(motion):
        raise ValueError('Original participant bodies differ from turn frames')
    for key in ('pedestrian_may_be_affected', 'vehicle_may_be_affected'):
        if type(context.get(key)) is not bool or not context.get(key + '_source'):
            raise ValueError('Potentially affected participant needs separately cited context: ' + key)
    if not context.get('listener_id') or not context.get('listener_position_source'):
        raise ValueError('Listener audio needs a sourced location and identity')
    actor_types = context.get('participant_types')
    if not isinstance(actor_types, dict) or not actor_types or any(
        kind not in ('pedestrian', 'vehicle') for kind in actor_types.values()
    ) or not context.get('participant_geometry_source'):
        raise ValueError('Participant identities, types and original geometry source required')
    initial_yaw = float(motion[0]['ego_yaw_deg'])
    if not isfinite(initial_yaw):
        raise ValueError('Original turn yaw is not finite')
    observations = []
    previous = None
    body_series = {actor_id: [] for actor_id in actor_types}
    ego_series = []
    for index, (movement, signal, participant) in enumerate(zip(motion, signals, participants)):
        frame, time_s = movement.get('frame'), movement.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original turn frame/time identity missing')
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > 1e-4):
            raise ValueError('Original turn frames are not joined at 20 Hz')
        previous = frame, time_s
        if signal.get('frame') != frame or signal.get('time_s') != time_s:
            raise ValueError('Original signal/audio frame join failed')
        if participant.get('frame') != frame or participant.get('time_s') != time_s:
            raise ValueError('Original participant/body frame join failed')
        bodies = participant.get('bodies')
        if not isinstance(bodies, dict) or set(bodies) != set(actor_types):
            raise ValueError('Original participant identities differ from sourced context')
        ego_series.append(_body(movement, 'ego'))
        for actor_id in actor_types:
            body_series[actor_id].append(_body(bodies[actor_id], actor_id))
        if signal.get('listener_id') != context['listener_id']:
            raise ValueError('Listener identity differs from sourced context')
        indicator = signal.get('indicator_readback')
        if indicator not in ('off', 'left', 'right'):
            raise ValueError('Turn indicator requires a Native side readback')
        yaw = float(movement['ego_yaw_deg'])
        if not isfinite(yaw):
            raise ValueError('Original turn yaw is not finite')
        delta = atan2(sin(radians(yaw - initial_yaw)), cos(radians(yaw - initial_yaw)))
        samples = signal.get('listener_audio_samples')
        if samples is None:
            if (context['pedestrian_may_be_affected'] or
                    signal.get('listener_audio_status') != 'not_collected_no_affected_pedestrian'):
                raise ValueError('Original listener audio required when a pedestrian may be affected')
            audio_rms = None
        else:
            audio_rms = _rms(samples)
        observations.append({'frame': frame, 'time_s': time_s,
                             'yaw_change_deg': delta * 180 / 3.141592653589793,
                             'indicator_readback': indicator,
                             'listener_audio_rms': audio_rms})
    onset = next((i for i, row in enumerate(observations)
                  if abs(row['yaw_change_deg']) > .5), None)
    if onset is None or onset == 0:
        raise ValueError('No measured turn onset after a direct course')
    before = observations[:onset]
    direction = 'left' if observations[onset]['yaw_change_deg'] > 0 else 'right'
    clearance = {}
    for actor_id, series in body_series.items():
        gaps = [sqrt((ego[0] - other[0]) ** 2 + (ego[1] - other[1]) ** 2)
                - ego[2] - other[2] for ego, other in zip(ego_series, series)]
        clearance[actor_id] = {
            'type': actor_types[actor_id],
            'minimum_sampled_surface_gap_m': min(gaps),
            'surface_gap_at_turn_onset_m': gaps[onset],
            'constant_velocity_proxy_at_turn_onset': _closing_proxy(
                ego_series[onset], ego_series[onset - 1], series[onset],
                series[onset - 1], .05),
        }
    return {'format': 'worker-turn-signal-observation',
            'sources': {'ego_turn_motion.jsonl': motion_hash,
                        'ego_signal_audio.jsonl': signal_hash,
                        'affected_participants.json': context_hash,
                        'participant_bodies.jsonl': participant_hash},
            'frame_count': len(observations), 'turn_onset_frame': observations[onset]['frame'],
            'turn_direction': direction, 'pedestrian_may_be_affected': context['pedestrian_may_be_affected'],
            'vehicle_may_be_affected': context['vehicle_may_be_affected'],
            'max_pre_turn_listener_audio_rms': max((row['listener_audio_rms'] for row in before
                                                   if row['listener_audio_rms'] is not None), default=None),
            'pre_turn_indicator_frames': [row['frame'] for row in before if row['indicator_readback'] == direction],
            'participant_clearance': clearance,
            'observations': observations, 'clearly_audible_legal_judgment': None,
            'reasonable_safety_legal_judgment': None,
            'appropriate_signal_legal_judgment': None}
